<template>
  <div class="cjc-root">
    <header class="cjc-hero">
      <div class="cjc-hero__grid"></div>
      <div class="cjc-hero__inner">
        <div class="cjc-hero__eyebrow">
          <span class="cjc-hero__eyebrow-dot"></span>System Configuration
        </div>
        <div class="cjc-hero__row">
          <div>
            <h1 class="cjc-hero__title">Scheduled Jobs</h1>
            <p class="cjc-hero__sub">
              Background jobs that run on a schedule — when they run, and
              whether the last run succeeded.
            </p>
          </div>
          <button
            class="cjc-btn cjc-btn--outline"
            :disabled="loading"
            @click="loadAll"
          >
            <v-icon size="15" color="rgba(255,255,255,0.8)"
              >mdi-refresh</v-icon
            >Refresh
          </button>
        </div>
      </div>
    </header>

    <div v-if="loading" class="cjc-loading">
      <v-progress-circular indeterminate color="#6366f1" size="36" width="3" />
      <span>Loading…</span>
    </div>
    <v-alert v-if="error" type="error" dense outlined class="mx-4 mt-3">{{
      error
    }}</v-alert>

    <div v-if="!loading" class="cjc-body">
      <div v-for="job in jobs" :key="job.key" class="cjc-card">
        <div class="cjc-card__head">
          <div>
            <div class="cjc-card__name">{{ job.description || job.key }}</div>
            <div class="cjc-card__key">{{ job.key }}</div>
          </div>
          <div class="cjc-card__head-right">
            <span
              class="cjc-chip"
              :class="'cjc-chip--' + statusFor(job).tone"
            >
              <span class="cjc-chip__dot"></span>{{ statusFor(job).label }}
            </span>
            <button
              v-if="editingKey !== job.key"
              class="cjc-btn cjc-btn--outline cjc-btn--sm"
              @click="startEdit(job)"
            >
              <v-icon size="14">mdi-pencil-outline</v-icon> Edit
            </button>
            <template v-else>
              <button
                class="cjc-btn cjc-btn--ghost cjc-btn--sm"
                @click="cancelEdit"
              >
                Cancel
              </button>
              <button
                class="cjc-btn cjc-btn--save cjc-btn--sm"
                :disabled="saving || !canSave"
                @click="save(job)"
              >
                <v-progress-circular
                  v-if="saving"
                  size="13"
                  width="2"
                  indeterminate
                  color="white"
                />
                {{ saving ? "Saving…" : "Save" }}
              </button>
            </template>
          </div>
        </div>

        <!-- ── Read-only summary ─────────────────────────────── -->
        <div v-if="editingKey !== job.key" class="cjc-summary">
          <div class="cjc-summary__row">
            <span class="cjc-summary__label">Enabled</span>
            <span class="cjc-summary__value">{{
              job.enabled ? "Yes" : "No"
            }}</span>
          </div>
          <div class="cjc-summary__row">
            <span class="cjc-summary__label">Schedule</span>
            <span class="cjc-summary__value cjc-mono">{{
              job.schedule
            }}</span>
            <span class="cjc-summary__hint">{{
              describeCron(job.schedule)
            }}</span>
          </div>
          <div class="cjc-summary__row" v-if="job.liveNextRun">
            <span class="cjc-summary__label">Next run</span>
            <span class="cjc-summary__value">{{
              formatDate(job.liveNextRun)
            }}</span>
          </div>
          <div
            class="cjc-summary__row"
            v-for="f in fieldsFor(job)"
            :key="f.key"
          >
            <span class="cjc-summary__label">{{ f.label }}</span>
            <span class="cjc-summary__value"
              >{{ job[f.key] }} {{ f.unit }}</span
            >
          </div>

          <div class="cjc-status">
            <div class="cjc-status__row">
              <span class="cjc-status__label">Last run</span>
              <span class="cjc-status__value">{{
                job.lastFinishedAt
                  ? formatDate(job.lastFinishedAt)
                  : "Never"
              }}</span>
            </div>
            <div class="cjc-status__row" v-if="job.lastDurationMs != null">
              <span class="cjc-status__label">Duration</span>
              <span class="cjc-status__value"
                >{{ job.lastDurationMs }} ms</span
              >
            </div>
            <div class="cjc-status__row" v-if="job.lastTrigger">
              <span class="cjc-status__label">Trigger</span>
              <span class="cjc-status__value">{{
                job.lastTrigger === "manual" ? "Manual" : "Schedule"
              }}</span>
            </div>
            <div class="cjc-status__row" v-if="job.lastError">
              <span class="cjc-status__label">Error</span>
              <span class="cjc-status__value cjc-status__value--error">{{
                job.lastError
              }}</span>
            </div>
            <div class="cjc-status__row" v-if="job.lastResultText">
              <span class="cjc-status__label">Result</span>
              <span class="cjc-status__value cjc-mono">{{
                job.lastResultText
              }}</span>
            </div>
            <div
              class="cjc-status__row"
              v-if="job.liveSkippedCount"
            >
              <span class="cjc-status__label">Skipped</span>
              <span class="cjc-status__value"
                >{{ job.liveSkippedCount }} time(s) — previous run still in
                progress</span
              >
            </div>
          </div>
        </div>

        <!-- ── Editor ─────────────────────────────────────────── -->
        <div v-else class="cjc-editor">
          <v-switch
            v-model="draft.enabled"
            label="Enabled"
            color="#4f46e5"
            dense
            hide-details
            class="cjc-editor__switch"
          />

          <div class="cjc-mode-tabs">
            <button
              class="cjc-mode-tab"
              :class="{ 'cjc-mode-tab--active': draft.mode === 'simple' }"
              @click="draft.mode = 'simple'"
            >
              Simple
            </button>
            <button
              class="cjc-mode-tab"
              :class="{ 'cjc-mode-tab--active': draft.mode === 'advanced' }"
              @click="draft.mode = 'advanced'"
            >
              Advanced (cron)
            </button>
          </div>

          <!-- Simple builder -->
          <div v-if="draft.mode === 'simple'" class="cjc-builder">
            <v-alert
              v-if="!builderMatchesSchedule"
              type="info"
              dense
              outlined
              class="cjc-builder__notice"
            >
              This schedule doesn't match a simple pattern. Changing anything
              below will replace it.
            </v-alert>

            <div class="cjc-builder__row">
              <v-select
                :items="frequencyOptions"
                :value="builderView.frequency"
                label="Runs"
                dense
                outlined
                hide-details
                class="cjc-builder__field"
                @change="(v) => updateBuilder({ frequency: v })"
              />

              <template v-if="builderView.frequency !== 'interval'">
                <v-text-field
                  type="number"
                  min="0"
                  max="23"
                  :value="builderView.hour"
                  label="Hour (0–23)"
                  dense
                  outlined
                  hide-details
                  class="cjc-builder__field cjc-builder__field--sm"
                  @input="(v) => updateBuilder({ hour: v })"
                />
                <v-text-field
                  type="number"
                  min="0"
                  max="59"
                  :value="builderView.minute"
                  label="Minute (0–59)"
                  dense
                  outlined
                  hide-details
                  class="cjc-builder__field cjc-builder__field--sm"
                  @input="(v) => updateBuilder({ minute: v })"
                />
              </template>

              <template v-else>
                <v-text-field
                  type="number"
                  min="1"
                  max="23"
                  :value="builderView.intervalHours"
                  label="Every N hours"
                  dense
                  outlined
                  hide-details
                  class="cjc-builder__field cjc-builder__field--sm"
                  @input="(v) => updateBuilder({ intervalHours: v })"
                />
                <v-text-field
                  type="number"
                  min="0"
                  max="59"
                  :value="builderView.minute"
                  label="At minute"
                  dense
                  outlined
                  hide-details
                  class="cjc-builder__field cjc-builder__field--sm"
                  @input="(v) => updateBuilder({ minute: v })"
                />
              </template>
            </div>

            <div v-if="builderView.frequency === 'weekly'" class="cjc-days">
              <button
                v-for="d in DAY_OPTIONS"
                :key="d.value"
                class="cjc-day"
                :class="{
                  'cjc-day--active': builderView.days.includes(d.value),
                }"
                @click="toggleDay(d.value)"
              >
                {{ d.label }}
              </button>
            </div>
            <div
              v-if="
                builderView.frequency === 'weekly' &&
                !builderView.days.length
              "
              class="cjc-builder__warn"
            >
              Select at least one day.
            </div>

            <p class="cjc-builder__timezone">
              Times are in Africa/Maseru, regardless of the server's own
              clock.
            </p>
          </div>

          <!-- Advanced raw cron -->
          <div v-else class="cjc-advanced">
            <v-text-field
              v-model="draft.schedule"
              label="Cron expression"
              placeholder="0 2 * * *"
              dense
              outlined
              hide-details
              class="cjc-mono-field"
              @input="checkCron"
            />
            <p class="cjc-advanced__help">
              5 fields: minute hour day-of-month month day-of-week.
            </p>
          </div>

          <div class="cjc-preview">
            <template v-if="cronCheck.checking">
              <v-progress-circular
                indeterminate
                size="14"
                width="2"
                color="#6366f1"
              />
              <span>Checking…</span>
            </template>
            <template v-else-if="cronCheck.valid === true">
              <v-icon size="16" color="#22c55e">mdi-check-circle</v-icon>
              <span
                >Valid — next run
                {{
                  cronCheck.nextRun ? formatDate(cronCheck.nextRun) : "—"
                }}</span
              >
            </template>
            <template v-else-if="cronCheck.valid === false">
              <v-icon size="16" color="#ef4444">mdi-alert-circle</v-icon>
              <span>{{ cronCheck.error || "Invalid schedule" }}</span>
            </template>
          </div>

          <div
            v-if="fieldsFor(job).length"
            class="cjc-editor__settings"
          >
            <v-text-field
              v-for="f in fieldsFor(job)"
              :key="f.key"
              v-model.number="draft[f.key]"
              type="number"
              min="0"
              :label="f.label"
              :suffix="f.unit"
              :hint="f.help"
              persistent-hint
              dense
              outlined
              class="cjc-setting-field"
            />
          </div>
        </div>
      </div>

      <div v-if="!jobs.length" class="cjc-empty">No scheduled jobs found.</div>
    </div>

    <v-snackbar
      v-model="snackbar.show"
      :color="snackbar.color"
      timeout="3500"
      bottom
      >{{ snackbar.text }}</v-snackbar
    >
  </div>
</template>

<script>
// Labels + helper text for job-specific settings beyond enabled/schedule.
// A future job with settings not listed here still renders — just with a
// Title Case label and no helper text — rather than being hidden.
const FIELD_META = {
  workingDays: {
    label: "Review window",
    unit: "working days",
    help: "A reviewer who hasn't acted within this many working days is bypassed.",
  },
  reminderAfter: {
    label: "Reminder at",
    unit: "working days",
    help: "A reminder is sent this many working days in, before the bypass.",
  },
  catchUpDays: {
    label: "Catch-up window",
    unit: "days",
    help: "A 60th birthday found within this many days is still auto-terminated. Older than that is flagged for manual review instead.",
  },
};

const DAY_OPTIONS = [
  { value: 1, label: "Mon" },
  { value: 2, label: "Tue" },
  { value: 3, label: "Wed" },
  { value: 4, label: "Thu" },
  { value: 5, label: "Fri" },
  { value: 6, label: "Sat" },
  { value: 0, label: "Sun" },
];
const DAY_NAMES = {
  0: "Sun",
  1: "Mon",
  2: "Tue",
  3: "Wed",
  4: "Thu",
  5: "Fri",
  6: "Sat",
};

const DEFAULT_BUILDER = {
  frequency: "daily",
  hour: 2,
  minute: 0,
  days: [],
  intervalHours: 6,
};

const CONFIG_URL = "/fhir/Parameters/cron-jobs-config";

export default {
  name: "CronJobsConfig",

  data() {
    return {
      loading: true,
      error: null,
      saving: false,
      rawResource: null,
      jobs: [],
      editingKey: null,
      draft: null,
      cronCheck: { checking: false, valid: null, error: null, nextRun: null },
      cronCheckTimer: null,
      DAY_OPTIONS,
      snackbar: { show: false, text: "", color: "success" },
    };
  },

  computed: {
    frequencyOptions() {
      return [
        { text: "Daily", value: "daily" },
        { text: "Specific days of the week", value: "weekly" },
        { text: "Every N hours", value: "interval" },
      ];
    },
    builderMatchesSchedule() {
      return !!this.builderFromCron(this.draft && this.draft.schedule);
    },
    builderView() {
      if (!this.draft) return DEFAULT_BUILDER;
      return this.builderFromCron(this.draft.schedule) || DEFAULT_BUILDER;
    },
    canSave() {
      if (!this.draft) return false;
      if (this.draft.mode === "advanced") {
        return this.cronCheck.valid === true;
      }
      // Simple mode always produces a valid string by construction, except
      // "weekly" with nothing selected.
      return !(
        this.builderView.frequency === "weekly" &&
        !this.builderView.days.length
      );
    },
  },

  async mounted() {
    await this.loadAll();
  },

  methods: {
    // ── Load / merge ─────────────────────────────────────────────
    async loadAll() {
      this.loading = true;
      this.error = null;
      try {
        const [cfgRes, liveRes] = await Promise.all([
          fetch(CONFIG_URL),
          fetch("/site/general/cronJobsStatus"),
        ]);
        if (!cfgRes.ok) throw new Error(`HTTP ${cfgRes.status}`);
        this.rawResource = await cfgRes.json();
        const live = liveRes.ok ? await liveRes.json() : [];
        const liveByName = Object.fromEntries(live.map((j) => [j.name, j]));
        this.jobs = this.parseResource(this.rawResource, liveByName);
      } catch (e) {
        this.error = `Failed to load scheduled jobs: ${e.message}`;
      } finally {
        this.loading = false;
      }
    },

    parseResource(resource, liveByName) {
      return (resource.parameter || []).map((p) => {
        const get = (n) => {
          const x = (p.part || []).find((pt) => pt.name === n);
          return x?.valueString;
        };
        const live = liveByName[p.name] || {};
        const knownKeys = new Set([
          "enabled",
          "schedule",
          "lastTrigger",
          "lastStartedAt",
          "lastFinishedAt",
          "lastDurationMs",
          "lastOutcome",
          "lastResult",
          "lastError",
        ]);
        const extra = {};
        for (const part of p.part || []) {
          if (part.name && !knownKeys.has(part.name)) {
            const n = Number(part.valueString);
            extra[part.name] = Number.isFinite(n) ? n : part.valueString;
          }
        }
        return {
          key: p.name,
          description: live.description || "",
          enabled: get("enabled") === "true",
          schedule: get("schedule") || "",
          lastTrigger: get("lastTrigger") || null,
          lastFinishedAt: get("lastFinishedAt") || null,
          lastDurationMs:
            get("lastDurationMs") != null ? Number(get("lastDurationMs")) : null,
          lastOutcome: get("lastOutcome") || null,
          lastError: get("lastError") || null,
          lastResultText: get("lastResult") || null,
          liveNextRun: live.nextRun || null,
          liveRunning: !!live.running,
          liveSkippedCount: live.skippedCount || 0,
          ...extra,
        };
      });
    },

    fieldsFor(job) {
      return Object.keys(FIELD_META)
        .filter((k) => job[k] !== undefined)
        .map((k) => ({ key: k, ...FIELD_META[k] }));
    },

    statusFor(job) {
      if (job.liveRunning) return { tone: "running", label: "Running…" };
      if (!job.enabled) return { tone: "off", label: "Disabled" };
      if (!job.lastOutcome) return { tone: "idle", label: "Never run" };
      if (job.lastOutcome === "ok")
        return { tone: "ok", label: "Last run succeeded" };
      return { tone: "error", label: "Last run failed" };
    },

    formatDate(iso) {
      if (!iso) return "—";
      try {
        return new Date(iso).toLocaleString("en-GB", {
          timeZone: "Africa/Maseru",
          dateStyle: "medium",
          timeStyle: "short",
        }) + " (Maseru)";
      } catch (e) {
        return iso;
      }
    },

    describeCron(schedule) {
      const b = this.builderFromCron(schedule);
      if (!b) return "";
      const hhmm = `${String(b.hour).padStart(2, "0")}:${String(
        b.minute,
      ).padStart(2, "0")}`;
      if (b.frequency === "interval") {
        return `Every ${b.intervalHours}h, at minute ${b.minute}`;
      }
      if (b.frequency === "weekly") {
        const days = [...b.days]
          .sort((a, c) => a - c)
          .map((d) => DAY_NAMES[d])
          .join(", ");
        return `${hhmm} on ${days || "—"}`;
      }
      return `Daily at ${hhmm}`;
    },

    // ── cron <-> builder ─────────────────────────────────────────
    cronFromBuilder(b) {
      const minute = Math.min(59, Math.max(0, Number(b.minute) || 0));
      if (b.frequency === "interval") {
        const n = Math.min(23, Math.max(1, Number(b.intervalHours) || 1));
        return `${minute} */${n} * * *`;
      }
      const hour = Math.min(23, Math.max(0, Number(b.hour) || 0));
      if (b.frequency === "weekly" && b.days && b.days.length) {
        const days = [...b.days].sort((a, c) => a - c).join(",");
        return `${minute} ${hour} * * ${days}`;
      }
      return `${minute} ${hour} * * *`;
    },

    builderFromCron(schedule) {
      if (!schedule) return null;
      const parts = schedule.trim().split(/\s+/);
      if (parts.length !== 5) return null;
      const [min, hour, dom, month, dow] = parts;
      if (dom !== "*" || month !== "*") return null;
      if (!/^\d+$/.test(min)) return null;
      const minute = Number(min);
      if (minute > 59) return null;

      const intervalMatch = /^\*\/(\d+)$/.exec(hour);
      if (intervalMatch && dow === "*") {
        return {
          frequency: "interval",
          hour: 0,
          minute,
          days: [],
          intervalHours: Number(intervalMatch[1]),
        };
      }
      if (!/^\d+$/.test(hour)) return null;
      const h = Number(hour);
      if (h > 23) return null;

      if (dow === "*") {
        return { frequency: "daily", hour: h, minute, days: [], intervalHours: 6 };
      }
      if (/^[0-6](,[0-6])*$/.test(dow)) {
        return {
          frequency: "weekly",
          hour: h,
          minute,
          days: dow.split(",").map(Number),
          intervalHours: 6,
        };
      }
      return null;
    },

    updateBuilder(patch) {
      const current = this.builderFromCron(this.draft.schedule) || {
        ...DEFAULT_BUILDER,
      };
      const next = { ...current, ...patch };
      this.draft.schedule = this.cronFromBuilder(next);
      this.checkCron();
    },

    toggleDay(value) {
      const current = this.builderFromCron(this.draft.schedule) || {
        ...DEFAULT_BUILDER,
        frequency: "weekly",
      };
      const days = current.days.includes(value)
        ? current.days.filter((d) => d !== value)
        : [...current.days, value];
      this.updateBuilder({ days });
    },

    // ── Live validation ──────────────────────────────────────────
    checkCron() {
      clearTimeout(this.cronCheckTimer);
      const schedule = this.draft?.schedule;
      if (!schedule) {
        this.cronCheck = { checking: false, valid: null, error: null, nextRun: null };
        return;
      }
      this.cronCheck = { ...this.cronCheck, checking: true };
      this.cronCheckTimer = setTimeout(async () => {
        try {
          const r = await fetch(
            `/site/general/validateCron?schedule=${encodeURIComponent(schedule)}`,
          );
          const body = await r.json();
          this.cronCheck = {
            checking: false,
            valid: body.valid,
            error: body.error || null,
            nextRun: body.nextRun || null,
          };
        } catch (e) {
          this.cronCheck = {
            checking: false,
            valid: false,
            error: "Could not reach the server to validate",
            nextRun: null,
          };
        }
      }, 350);
    },

    // ── Edit / save ──────────────────────────────────────────────
    startEdit(job) {
      this.editingKey = job.key;
      // Job-specific fields (workingDays, reminderAfter, ...) are included
      // in this same object literal, not added afterwards - Vue 2 only
      // makes a reactive object's OWN properties reactive at the moment
      // it's assigned, so adding them in a follow-up loop would leave them
      // silently non-reactive.
      const extra = {};
      for (const f of this.fieldsFor(job)) {
        extra[f.key] = job[f.key];
      }
      this.draft = {
        enabled: job.enabled,
        schedule: job.schedule,
        mode: "simple",
        ...extra,
      };
      this.checkCron();
    },

    cancelEdit() {
      this.editingKey = null;
      this.draft = null;
      this.cronCheck = { checking: false, valid: null, error: null, nextRun: null };
    },

    async save(job) {
      if (!this.canSave) return;
      this.saving = true;
      try {
        const updated = JSON.parse(JSON.stringify(this.rawResource));
        const param = (updated.parameter || []).find(
          (p) => p.name === job.key,
        );
        if (!param) throw new Error(`"${job.key}" not found in resource`);
        param.part = param.part || [];

        const setPart = (name, value) => {
          const idx = param.part.findIndex((p) => p.name === name);
          const entry = { name, valueString: String(value) };
          if (idx === -1) param.part.push(entry);
          else param.part[idx] = entry;
        };
        setPart("enabled", this.draft.enabled ? "true" : "false");
        setPart("schedule", this.draft.schedule);
        for (const f of this.fieldsFor(job)) {
          setPart(f.key, this.draft[f.key]);
        }

        const r = await fetch(CONFIG_URL, {
          method: "PUT",
          headers: { "Content-Type": "application/fhir+json" },
          body: JSON.stringify(updated),
        });
        if (!r.ok) throw new Error(`HTTP ${r.status}`);
        this.rawResource = await r.json();

        // Apply immediately - a schedule change needs the job's node-cron
        // task destroyed and recreated, which the next server restart
        // would do anyway, but nobody should have to wait for that.
        const reloadRes = await fetch("/site/general/reloadCronJobs", {
          method: "POST",
        });
        if (!reloadRes.ok) {
          this.showSnackbar(
            "Saved, but couldn't apply immediately - it will take effect on next restart",
            "warning",
          );
        } else {
          this.showSnackbar("Saved and applied", "success");
        }

        this.editingKey = null;
        this.draft = null;
        await this.loadAll();
      } catch (e) {
        this.showSnackbar(`Save failed: ${e.message}`, "error");
      } finally {
        this.saving = false;
      }
    },

    showSnackbar(text, color) {
      this.snackbar = { show: true, text, color };
    },
  },
};
</script>

<style scoped>
@import url("https://fonts.googleapis.com/css2?family=Sora:wght@300;400;500;600;700;800&family=JetBrains+Mono:wght@400;500&display=swap");
* {
  box-sizing: border-box;
}
.cjc-root {
  min-height: 100vh;
  background: #f5f4f2;
  font-family: "Sora", sans-serif;
}
.cjc-mono,
.cjc-mono-field >>> input {
  font-family: "JetBrains Mono", monospace;
}
.cjc-hero {
  background: linear-gradient(135deg, #0f172a 0%, #1e3a5f 55%, #1e40af 100%);
  padding: 32px 28px 36px;
  position: relative;
  overflow: hidden;
}
.cjc-hero__grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: linear-gradient(
      rgba(255, 255, 255, 0.04) 1px,
      transparent 1px
    ),
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
  background-size: 40px 40px;
}
.cjc-hero__inner {
  position: relative;
  z-index: 1;
  max-width: 1000px;
}
.cjc-hero__eyebrow {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
  font-size: 11px;
  font-weight: 600;
  color: rgba(165, 180, 252, 0.9);
  text-transform: uppercase;
  letter-spacing: 0.1em;
}
.cjc-hero__eyebrow-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #818cf8;
  box-shadow: 0 0 8px #818cf8;
}
.cjc-hero__row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
}
.cjc-hero__title {
  font-size: 28px;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.02em;
  margin: 0 0 6px;
}
.cjc-hero__sub {
  font-size: 13px;
  color: rgba(255, 255, 255, 0.55);
  max-width: 520px;
  line-height: 1.6;
  margin: 0;
}
.cjc-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 9px 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 600;
  font-family: inherit;
  border: none;
  cursor: pointer;
  transition: all 0.15s ease;
}
.cjc-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.cjc-btn--outline {
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.25);
}
.cjc-btn--outline:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.16);
}
.cjc-btn--ghost {
  background: transparent;
  color: #64748b;
}
.cjc-btn--ghost:hover {
  background: #eef0f3;
}
.cjc-btn--save {
  background: #4f46e5;
  color: #fff;
}
.cjc-btn--save:hover:not(:disabled) {
  background: #4338ca;
}
.cjc-btn--sm {
  padding: 6px 12px;
  font-size: 12px;
}
.cjc-loading {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 40px;
  color: #64748b;
  font-size: 13px;
}
.cjc-body {
  max-width: 1000px;
  margin: 0 auto;
  padding: 24px 20px 60px;
  display: flex;
  flex-direction: column;
  gap: 16px;
}
.cjc-card {
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 12px;
  padding: 20px 22px;
}
.cjc-card__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.cjc-card__name {
  font-size: 15px;
  font-weight: 700;
  color: #0f172a;
}
.cjc-card__key {
  font-size: 11px;
  color: #94a3b8;
  font-family: "JetBrains Mono", monospace;
  margin-top: 2px;
}
.cjc-card__head-right {
  display: flex;
  align-items: center;
  gap: 8px;
}
.cjc-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
}
.cjc-chip__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
}
.cjc-chip--ok {
  background: #dcfce7;
  color: #15803d;
}
.cjc-chip--ok .cjc-chip__dot {
  background: #22c55e;
}
.cjc-chip--error {
  background: #fee2e2;
  color: #b91c1c;
}
.cjc-chip--error .cjc-chip__dot {
  background: #ef4444;
}
.cjc-chip--idle {
  background: #f1f5f9;
  color: #64748b;
}
.cjc-chip--idle .cjc-chip__dot {
  background: #94a3b8;
}
.cjc-chip--off {
  background: #f1f5f9;
  color: #94a3b8;
}
.cjc-chip--off .cjc-chip__dot {
  background: #cbd5e1;
}
.cjc-chip--running {
  background: #dbeafe;
  color: #1d4ed8;
}
.cjc-chip--running .cjc-chip__dot {
  background: #3b82f6;
  animation: cjc-pulse 1.2s ease-in-out infinite;
}
@keyframes cjc-pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.3;
  }
}
.cjc-summary__row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 6px 0;
  font-size: 13px;
  border-bottom: 1px solid #f1f5f9;
}
.cjc-summary__label {
  width: 130px;
  flex-shrink: 0;
  color: #94a3b8;
  font-size: 12px;
}
.cjc-summary__value {
  color: #0f172a;
  font-weight: 500;
  /* A flex item's default min-width is auto (content-based), so an
     unbreakable value - a long word, a schedule string - would otherwise
     force this item, and the card around it, wider than the page instead
     of wrapping. */
  min-width: 0;
  overflow-wrap: anywhere;
}
.cjc-summary__hint {
  color: #94a3b8;
  font-size: 12px;
}
.cjc-status {
  margin-top: 12px;
  padding-top: 8px;
}
.cjc-status__row {
  display: flex;
  align-items: baseline;
  gap: 10px;
  padding: 4px 0;
  font-size: 12.5px;
}
.cjc-status__label {
  width: 130px;
  flex-shrink: 0;
  color: #94a3b8;
}
.cjc-status__value {
  color: #334155;
  /* Same fix as .cjc-summary__value above - this is where it actually
     bites: lastResult is a JSON blob with no spaces, so without this the
     row (and the card) is forced wide enough to fit it on one line. */
  min-width: 0;
  overflow-wrap: anywhere;
}
.cjc-status__value--error {
  color: #b91c1c;
}
.cjc-editor {
  display: flex;
  flex-direction: column;
  gap: 14px;
}
.cjc-editor__switch {
  margin-top: 0 !important;
}
.cjc-mode-tabs {
  display: flex;
  gap: 4px;
  background: #f1f5f9;
  border-radius: 8px;
  padding: 3px;
  width: fit-content;
}
.cjc-mode-tab {
  border: none;
  background: transparent;
  padding: 6px 14px;
  border-radius: 6px;
  font-size: 12.5px;
  font-weight: 600;
  color: #64748b;
  cursor: pointer;
  font-family: inherit;
}
.cjc-mode-tab--active {
  background: #fff;
  color: #0f172a;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.08);
}
.cjc-builder {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.cjc-builder__notice {
  margin: 0;
}
.cjc-builder__row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.cjc-builder__field {
  max-width: 260px;
}
.cjc-builder__field--sm {
  max-width: 140px;
}
.cjc-days {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}
.cjc-day {
  border: 1px solid #e2e8f0;
  background: #fff;
  color: #475569;
  padding: 6px 12px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  font-family: inherit;
}
.cjc-day--active {
  background: #4f46e5;
  border-color: #4f46e5;
  color: #fff;
}
.cjc-builder__warn {
  color: #b45309;
  font-size: 12px;
}
.cjc-builder__timezone {
  color: #94a3b8;
  font-size: 11.5px;
  margin: 0;
}
.cjc-advanced__help {
  color: #94a3b8;
  font-size: 11.5px;
  margin: 4px 0 0;
}
.cjc-preview {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12.5px;
  color: #475569;
  min-height: 18px;
}
.cjc-editor__settings {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  padding-top: 4px;
  border-top: 1px solid #f1f5f9;
}
/* Deliberately its own class rather than reusing cjc-builder__field--sm
   (140px, sized for a bare 2-digit hour/minute number). These fields carry
   a full label, a unit suffix, and a persistent hint sentence, all of which
   were getting crushed into 140px and overlapping - which read as the field
   not being there at all rather than just being cramped. */
.cjc-setting-field {
  width: 220px;
  flex: 0 0 220px;
}
.cjc-empty {
  text-align: center;
  color: #94a3b8;
  font-size: 13px;
  padding: 40px;
}
</style>
